// Send to code: the Figma side. Generated by build.mjs from this template and pipeline/01b_snapshot_plugin_api.js.
// Reads the variables and components with the same code as the pipeline, saves a named Figma version,
// and pushes the snapshot to a new branch figma/... in GitHub. GitHub Actions does the rest (figma-sync.yml).
const REPO = "thiago-ascendum/ascendum-design-system";
const API = "https://api.github.com/repos/" + REPO;

async function snapshot(SOURCE_VERSION_ARG) {
/*SNAPSHOT*/
}

async function gh(token, path, method, body) {
  const r = await fetch(API + path, {
    method: method || "GET",
    headers: { Authorization: "Bearer " + token, Accept: "application/vnd.github+json", "Content-Type": "application/json" },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await r.text();
  if (!r.ok) throw new Error("GitHub " + r.status + " on " + path + ": " + text.slice(0, 200));
  return text ? JSON.parse(text) : {};
}

figma.showUI(__html__, { width: 360, height: 460, themeColors: true });

(async () => {
  const cols = await figma.variables.getLocalVariableCollectionsAsync();
  const token = await figma.clientStorage.getAsync("githubToken");
  figma.ui.postMessage({ type: "init", collections: cols.map((c) => c.name), hasToken: !!token, user: figma.currentUser ? figma.currentUser.name : "" });
})();

figma.ui.onmessage = async (msg) => {
  try {
    if (msg.type === "saveToken") {
      await figma.clientStorage.setAsync("githubToken", msg.token.trim());
      figma.ui.postMessage({ type: "tokenSaved" });
      return;
    }
    if (msg.type !== "send") return;
    const token = await figma.clientStorage.getAsync("githubToken");
    if (!token) throw new Error("Add a GitHub token first.");
    const step = (text) => figma.ui.postMessage({ type: "step", text });

    step("Reading the file and saving a Figma version");
    const snap = await snapshot("Send to code: " + msg.message);
    const version = JSON.parse(snap).meta.figmaVersion;

    step("Sending to GitHub");
    const main = await gh(token, "/git/ref/heads/main");
    const base = await gh(token, "/git/commits/" + main.object.sha);
    const request = { message: msg.message, collections: msg.collections, user: figma.currentUser ? figma.currentUser.name : null, sentAt: new Date().toISOString() };
    const blobSnap = await gh(token, "/git/blobs", "POST", { content: snap, encoding: "utf-8" });
    const blobReq = await gh(token, "/git/blobs", "POST", { content: JSON.stringify(request, null, 2), encoding: "utf-8" });
    const tree = await gh(token, "/git/trees", "POST", { base_tree: base.tree.sha, tree: [
      { path: "figma-inbox/snapshot.json", mode: "100644", type: "blob", sha: blobSnap.sha },
      { path: "figma-inbox/request.json", mode: "100644", type: "blob", sha: blobReq.sha },
    ] });
    const commit = await gh(token, "/git/commits", "POST", { message: "Send to code: " + msg.message, tree: tree.sha, parents: [main.object.sha] });
    const branch = "figma/" + new Date().toISOString().replace(/[-:]/g, "").replace(/\..*/, "").replace("T", "-");
    await gh(token, "/git/refs", "POST", { ref: "refs/heads/" + branch, sha: commit.sha });

    figma.ui.postMessage({ type: "done", version: version.id, branch,
      actions: "https://github.com/" + REPO + "/actions/workflows/figma-sync.yml",
      pulls: "https://github.com/" + REPO + "/pulls" });
  } catch (e) {
    figma.ui.postMessage({ type: "error", text: String(e && e.message || e) });
  }
};
